use crate::protocol::codec::{SshReader, SshWriter};
use crate::{
    SshAgentIdentity, SshAgentRequest, SshAgentResponse, SshCertificate, SshPublicKey,
    SshPublicKeyBlob, SshUserauthSigningPayload,
};
use p256::elliptic_curve::sec1::ToSec1Point;

// Public fixture generated by ssh-keygen: ECDSA P-256 host certificate signed
// by an Ed25519 CA. Parsing a signing payload does not check certificate time.
const HOST_CERTIFICATE: &[u8] = include_bytes!("ecdsa_host_cert.bin");

keyringd_testkit::scenario! {
    group "OpenSSH host-bound authentication" {
        case "Retains an ECDSA host certificate whose CA algorithm is unsupported" {
            spec "https://github.com/openssh/openssh-portable/blob/master/PROTOCOL#L323-L348"
            why "The server host-key field must not depend on the agent's ability to parse its CA key."
            verify "a normal sign request preserves the host certificate and identities encode its original bytes" {
                assert!(SshCertificate::from_bytes(HOST_CERTIFICATE).is_err());
                let host = SshPublicKeyBlob::from_bytes(HOST_CERTIFICATE).unwrap();
                let q = p256::SecretKey::from_slice(&[1; 32]).unwrap().public_key().to_sec1_point(false);
                let user = SshPublicKey::from_ecdsa_pubkey(q.as_bytes()).unwrap().into_key_blob();
                let mut data = SshWriter::new();
                data.write_string(b"session");
                data.write_u8(50);
                for field in [b"alice".as_slice(), b"ssh-connection", b"publickey-hostbound-v00@openssh.com"] {
                    data.write_string(field);
                }
                data.write_u8(1);
                data.write_string(user.algorithm().as_bytes());
                data.write_string(user.as_bytes());
                data.write_string(host.as_bytes());
                let data = data.into_bytes();
                let mut wire = SshWriter::new();
                wire.write_u8(13);
                wire.write_string(user.as_bytes());
                wire.write_string(&data);
                wire.write_u32(0);
                let SshAgentRequest::Sign(request) = SshAgentRequest::from_bytes(&wire.into_bytes()).unwrap() else { panic!("expected a sign request") };
                let payload = SshUserauthSigningPayload::from_bytes(request.data()).unwrap();
                assert_eq!(request.key_blob(), &user);
                assert_eq!(payload.key_blob(), &user);
                assert_eq!(payload.host_key_blob().unwrap().as_bytes(), HOST_CERTIFICATE);
                assert_eq!(payload.host_key_blob().unwrap(), &host);
                assert_eq!(request.data(), data);
                let reply = SshAgentResponse::IdentitiesAnswer { identities: vec![SshAgentIdentity::new(host, "host")] }.to_bytes().unwrap();
                let mut reader = SshReader::new(&reply);
                assert_eq!(reader.read_u8().unwrap(), 12);
                assert_eq!(reader.read_u32().unwrap(), 1);
                assert_eq!(reader.read_string().unwrap(), HOST_CERTIFICATE);
                assert_eq!(reader.read_string().unwrap(), b"host");
                reader.finish().unwrap();
            }
        }
    }
}
